      if ("'!['"'input', 'steps', 'failAttempts'].includes(field)) invalid(field, 'Unknown field.');
    input = value.input;
    if (Object.hasOwn(value, 'steps')) steps = value.steps;
    if (Object.hasOwn(value, 'failAttempts')) failAttempts = value.failAttempts;
    if (typeof input "'!== '"'string' || input.length < 1 || input.length > 1000 || "'!input.trim())
      invalid('"'input', 'Must be a nonblank string of 1–1000 characters.');
    if (typeof steps "'!== '"'number' || "'!Number.isInteger(steps) || steps < 1 || steps > 20)
