    const id = randomUUID(), now = new Date().toISOString();
    db.prepare('INSERT INTO jobs (id,input,steps,failAttempts,createdAt,updatedAt,idempotencyKey) VALUES (?,?,?,?,?,?,?)')
      .run(id, input as string, steps as number, failAttempts as number, now, now, key as string ?? null);
    const job = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
