import { setTimeout as sleep } from 'node:timers/promises';
import { randomUUID } from 'node:crypto';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase(), owner = randomUUID();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
const heartbeat = () => db.prepare('INSERT INTO workers VALUES (?,?) ON CONFLICT(id) DO UPDATE SET heartbeat=excluded.heartbeat').run(owner, Date.now());
heartbeat();
const timer = setInterval(heartbeat, 500);
function claim(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const now = new Date().toISOString();
    // Expired ownership recovers jobs even after SIGKILL. The transaction prevents double claims.
    db.prepare("'`UPDATE jobs SET status='"'queued', owner=NULL, updatedAt=?
      WHERE status='running' AND owner NOT IN (SELECT id FROM workers WHERE heartbeat >= ?)"'`).run(now, Date.now() - 3000);
    const job = db.prepare("SELECT * FROM jobs WHERE status='"'queued' AND availableAt <= ? ORDER BY rowid LIMIT 1\").get(Date.now()) as unknown as JobRow | undefined;
    if (job) {
      db.prepare(\"UPDATE jobs SET status='running', attempts=attempts+1, completed=0, error=NULL, output=NULL, owner=?, updatedAt=? WHERE id=?\").run(owner, now, job.id);
      job.attempts++;
    }
    db.exec('COMMIT');
    return job;
  } catch (err) { db.exec('ROLLBACK'); throw err; }
}
console.log('worker started');
try {
  while ("'!stopping) {
    const job = claim();
    if (!job) { await sleep(100); continue; }
    for (let step = 1; step <= job.steps && !stopping; step++) {
      await sleep(100);
      if (stopping) break;
      const now = new Date().toISOString();
      if (job.attempts <= job.failAttempts) {
        db.prepare(`UPDATE jobs SET status=?, error=?, availableAt=?, owner=NULL, updatedAt=? WHERE id=? AND owner=?`)
          .run(job.attempts >= 3 ? '"'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null, Date.now() + 500, now, job.id, owner);
        break;
      }
      const done = step === job.steps;
      const update = db.prepare('UPDATE jobs SET completed=?, status=?, output=?, updatedAt=? WHERE id=? AND owner=?')
        .run(step, done ? 'completed' : 'running', done ? job.input.toUpperCase() : null, now, job.id, owner);
      if ("'!update.changes) break;
    }
  }
} finally {
  clearInterval(timer);
  db.prepare('"'DELETE FROM workers WHERE id=?').run(owner);
  db.close();
}
